 async function capture(indices){return Promise.all(witnesses.filter(w=>indices.includes(w.deck)).map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),10000);w.port.onmessage=async({data})=>{if(data.type==='done'){clearTimeout(timer);resolve({deck:w.deck,channel:w.channel,startFrame:data.startFrame,frames:data.data.length,quanta:data.quanta,errors:data.errors,sha256:await sha(data.data.buffer),base64:base64(new Uint8Array(data.data.buffer))});}};w.port.postMessage({type:'capture',id:'tempo163',frames:Math.round(.3*engine.ctx.sampleRate)});})))}
