  click(button('grid'));$('#grid-bpm').value='120';$('#grid-offset').value='0';click('#grid-clear');for(const marker of [{time:1,bpm:150},{time:1.8,bpm:90}]){$('#grid-warp-time').value=marker.time;$('#grid-warp-bpm').value=marker.bpm;click('#grid-marker');}click('#grid-save');await until(()=>!$('#modal').open,'Save grid');
  click('[data-panel="settings"]');const setting=$('[data-setting="Sync Mode"]');setting.value='Smart Sync';setting.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');
  async function seek(position){const el=$('[data-seek="0"]');if(position===track.duration){$('[data-seek="0"]').dispatchEvent(new KeyboardEvent('keydown',{key:'End',bubbles:true}));await until(()=>engine.position(deck)===track.duration&&!deck.processing,'Seek End');return;}$('[data-seek="0"]').dispatchEvent(new KeyboardEvent('keydown',{key:'Home',bubbles:true}));await until(()=>engine.position(deck)===0&&!deck.processing,'Seek Home');for(let n=0;n<position;n++){$('[data-seek="0"]').dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));await until(()=>Math.abs(engine.position(deck)-(n+1))<1e-8&&!deck.processing,'Seek '+(n+1));}}
